package dev.pocketengine.browser;

import dev.pocketengine.store.TaskStore;
import java.util.UUID;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

public final class BrowserResearchPagesTest {
    static final String TASK=UUID.randomUUID().toString(),RUN=UUID.randomUUID().toString(),SESSION=UUID.randomUUID().toString(),SPACE=UUID.randomUUID().toString();
    static JSONObject manifest(JSONObject...pages)throws Exception {JSONArray rows=new JSONArray();for(JSONObject page:pages)rows.put(page);return new JSONObject().put("version",1).put("taskId",TASK).put("runId",RUN).put("epoch",2).put("profileId","owner-default").put("profileRevision",1).put("browserSessionId",SESSION).put("browserSpaceId",SPACE).put("revision",1).put("pages",rows).put("phase","active").put("automaticReplayAllowed",false).put("actionRefsRestored",false);}
    static JSONObject task(JSONObject value)throws Exception{return new JSONObject().put("id",TASK).put("events",new JSONArray().put(new JSONObject().put("type",BrowserResearchPages.EVENT).put("manifest",value).put("manifestFingerprint",TaskStore.capabilityFingerprint(value))));}
    @Test public void threeLogicalPagesPersistWithoutPretendingTheirOldRenderersAreAlive()throws Exception {JSONObject m=manifest(BrowserResearchPages.page(UUID.randomUUID().toString(),"https://one.example/a","来源一","ready","task"),BrowserResearchPages.page(UUID.randomUUID().toString(),"https://two.example/b","来源二","renderer_gone","task"),BrowserResearchPages.page(UUID.randomUUID().toString(),"https://login.example/","登录页","owner_control","owner_adopted"));BrowserResearchPages.validate(m);JSONObject restored=BrowserResearchPages.fromTask(task(new JSONObject(m.toString())));assertEquals(3,restored.getJSONArray("pages").length());assertFalse(restored.getBoolean("automaticReplayAllowed"));assertFalse(restored.getBoolean("actionRefsRestored"));assertFalse(restored.toString().contains("tabGeneration"));assertTrue(restored.getJSONArray("pages").getJSONObject(1).getBoolean("needsFreshObservation"));}
    @Test public void loginRedirectQueryAndUserInfoCannotBecomeRecoveryCredentials()throws Exception {JSONObject page=BrowserResearchPages.page(UUID.randomUUID().toString(),"https://login.example/callback?code=private-code#token","https://login.example/callback?code=private-code#token","owner_control","task");assertEquals("https://login.example/callback",page.getString("url"));assertTrue(page.getBoolean("urlQueryOmitted"));assertFalse(page.toString().contains("private-code"));assertEquals("",BrowserResearchPages.page(UUID.randomUUID().toString(),"https://user:secret@example.com/","bad","unknown","task").getString("url"));}
    @Test public void manifestCannotRestorePermissionsOrInventAReplacementPage()throws Exception {String id=UUID.randomUUID().toString();JSONObject m=manifest(BrowserResearchPages.page(id,"https://example.com/a","a","ready","task"));assertEquals(id,BrowserResearchPages.required(m,id).getString("logicalPageId"));assertThrows(SecurityException.class,()->BrowserResearchPages.required(m,UUID.randomUUID().toString()));assertThrows(SecurityException.class,()->BrowserResearchPages.validate(new JSONObject(m.toString()).put("actionRefsRestored",true)));assertThrows(SecurityException.class,()->BrowserResearchPages.validate(new JSONObject(m.toString()).put("approvalId",UUID.randomUUID().toString())));}
    @Test public void modifiedPersistedVersionOrOtherTaskCannotBeReadAsThisRecoveryManifest()throws Exception {JSONObject m=manifest(BrowserResearchPages.page(UUID.randomUUID().toString(),"https://example.com/a","a","ready","task")),saved=task(m);saved.getJSONArray("events").getJSONObject(0).getJSONObject("manifest").getJSONArray("pages").getJSONObject(0).put("url","https://other.example/");assertThrows(SecurityException.class,()->BrowserResearchPages.fromTask(saved));JSONObject wrong=task(manifest());wrong.put("id",UUID.randomUUID().toString());assertThrows(SecurityException.class,()->BrowserResearchPages.fromTask(wrong));}
    @Test public void stableLogicalIdentityDoesNotMakeDuplicatePhysicalOrActionIdsValid()throws Exception {String id=UUID.randomUUID().toString();JSONObject m=manifest(BrowserResearchPages.page(id,"https://example.com/a","a","ready","task"),BrowserResearchPages.page(id,"https://example.com/b","b","closed","task"));assertThrows(SecurityException.class,()->BrowserResearchPages.validate(m));assertThrows(IllegalArgumentException.class,()->BrowserResearchPages.page("n0","https://example.com/","bad","ready","task"));}
    @Test public void recoveryAddressesPreserveRawEscapedPathIdentityWhenOnlyQueryAndFragmentAreRemoved()throws Exception {String path="/item/a%2Fb/%2E/%2e%2E/keep%3Fpart";JSONObject row=BrowserResearchPages.page(UUID.randomUUID().toString(),"https://example.com"+path+"?token=omitted#part","encoded resource","ready","task");assertEquals("https://example.com"+path,row.getString("url"));assertTrue(row.getBoolean("urlQueryOmitted"));assertEquals(path,new java.net.URI(row.getString("url")).getRawPath());BrowserResearchPages.validate(manifest(row));}
    @Test public void oldTasksWithoutManifestsStayReadableWithoutInventedRecoveryState()throws Exception {assertNull(BrowserResearchPages.fromTask(new JSONObject().put("id",TASK).put("events",new JSONArray())));}
}
